import colorsys
import hashlib
import textwrap
from collections import Counter, defaultdict
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import viktor as vkt
from viktor import Color, TableCell

try:
    import ifcopenshell
    import ifcopenshell.api
except ImportError:  # pragma: no cover
    ifcopenshell = None


NO_MATERIAL_LABEL = "<No material>"
UNNAMED_MATERIAL_LABEL = "<Unnamed material>"
DEFAULT_NO_MATERIAL_RGB = (180, 180, 180)


def _require_ifcopenshell():
    if ifcopenshell is None:
        raise vkt.UserError(
            "Python dependency 'ifcopenshell' is missing. "
            "Add it to requirements.txt (e.g. 'ifcopenshell') and redeploy the app."
        )


def _unique_preserve_order(items: Iterable[str]) -> List[str]:
    seen = set()
    out = []
    for it in items:
        if it in seen:
            continue
        seen.add(it)
        out.append(it)
    return out


def _normalize_material_name(name: Optional[str]) -> str:
    if name is None:
        return ""
    return str(name).strip()


def _safe_style_name(name: str) -> str:
    allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
    cleaned = "".join(ch if ch in allowed else "_" for ch in name)
    return (cleaned[:60] if cleaned else "Material")


def _color_from_material_name(name: str) -> Tuple[int, int, int]:
    """Deterministic (unique-ish) color for a material name."""
    digest = hashlib.md5(name.encode("utf-8")).hexdigest()  # nosec - not for security
    hue = int(digest[:8], 16) / 0xFFFFFFFF
    sat = 0.60
    val = 0.90
    r, g, b = colorsys.hsv_to_rgb(hue, sat, val)
    return int(round(r * 255)), int(round(g * 255)), int(round(b * 255))


def _extract_material_names(relating_material) -> List[str]:
    """Recursively extract IfcMaterial names from the different IFC material assignment patterns."""

    if relating_material is None:
        return []

    if relating_material.is_a("IfcMaterial"):
        return [_normalize_material_name(relating_material.Name) or UNNAMED_MATERIAL_LABEL]

    if relating_material.is_a("IfcMaterialLayerSetUsage"):
        return _extract_material_names(relating_material.ForLayerSet)

    if relating_material.is_a("IfcMaterialLayerSet"):
        names = []
        for layer in (relating_material.MaterialLayers or []):
            if hasattr(layer, "Material"):
                names.extend(_extract_material_names(layer.Material))
        return names

    if relating_material.is_a("IfcMaterialProfileSetUsage"):
        return _extract_material_names(relating_material.ForProfileSet)

    if relating_material.is_a("IfcMaterialProfileSet"):
        names = []
        for prof in (relating_material.MaterialProfiles or []):
            if hasattr(prof, "Material"):
                names.extend(_extract_material_names(prof.Material))
        return names

    if relating_material.is_a("IfcMaterialConstituentSet"):
        names = []
        for c in (relating_material.MaterialConstituents or []):
            if hasattr(c, "Material"):
                names.extend(_extract_material_names(c.Material))
        return names

    if relating_material.is_a("IfcMaterialList"):
        names = []
        for m in (relating_material.Materials or []):
            names.extend(_extract_material_names(m))
        return names

    name = _normalize_material_name(getattr(relating_material, "Name", ""))
    return [name] if name else []


def _get_material_names_for_element(element) -> List[str]:
    """Get material names directly from IfcRelAssociatesMaterial, plus fallback via type."""

    names: List[str] = []

    for rel in (getattr(element, "HasAssociations", None) or []):
        try:
            if rel and rel.is_a("IfcRelAssociatesMaterial"):
                names.extend(_extract_material_names(rel.RelatingMaterial))
        except Exception:
            continue

    # Often materials are assigned to the element type instead of the instance.
    if not names:
        for rel in (getattr(element, "IsDefinedBy", None) or []):
            try:
                if rel and rel.is_a("IfcRelDefinesByType") and rel.RelatingType:
                    type_obj = rel.RelatingType
                    for r2 in (getattr(type_obj, "HasAssociations", None) or []):
                        if r2 and r2.is_a("IfcRelAssociatesMaterial"):
                            names.extend(_extract_material_names(r2.RelatingMaterial))
            except Exception:
                continue

    names = [_normalize_material_name(n) for n in names]
    names = [n for n in names if n]
    return _unique_preserve_order(names)


def _write_ifc_to_temp_file(ifc_bytes: bytes) -> Path:
    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
        tmp.write(ifc_bytes)
        return Path(tmp.name)


def _open_ifc_model_from_vkt_file(vkt_ifc_file: vkt.File):
    _require_ifcopenshell()
    path = _write_ifc_to_temp_file(vkt_ifc_file.getvalue())
    return ifcopenshell.open(str(path))


def _build_material_counts(model, include_openings: bool) -> Counter:
    counts: Counter = Counter()

    for elem in model.by_type("IfcElement"):
        # Most users do not want openings to count towards a take-off.
        if (not include_openings) and elem.is_a("IfcOpeningElement"):
            continue

        mat_names = _get_material_names_for_element(elem)
        if not mat_names:
            mat_names = [NO_MATERIAL_LABEL]

        # Count each material at most once per element.
        for m in set(mat_names):
            counts[m] += 1

    return counts


def _build_counts_and_colors(model, include_openings: bool) -> Tuple[Counter, Dict[str, Tuple[int, int, int]]]:
    counts = _build_material_counts(model, include_openings=include_openings)

    colors: Dict[str, Tuple[int, int, int]] = {
        name: _color_from_material_name(name)
        for name in counts.keys()
        if name not in {NO_MATERIAL_LABEL, UNNAMED_MATERIAL_LABEL}
    }
    colors.setdefault(NO_MATERIAL_LABEL, DEFAULT_NO_MATERIAL_RGB)
    colors.setdefault(UNNAMED_MATERIAL_LABEL, DEFAULT_NO_MATERIAL_RGB)

    return counts, colors


def _apply_material_based_coloring(model, colors: Dict[str, Tuple[int, int, int]]):
    """Attach IFC surface styles to IfcMaterial entities so the IFC viewer can color by material."""

    mats_by_name: Dict[str, List] = defaultdict(list)
    for m in model.by_type("IfcMaterial"):
        nm = _normalize_material_name(getattr(m, "Name", ""))
        if nm:
            mats_by_name[nm].append(m)

    for name, rgb in colors.items():
        if name in {NO_MATERIAL_LABEL, UNNAMED_MATERIAL_LABEL}:
            continue

        r, g, b = (c / 255.0 for c in rgb)
        style = ifcopenshell.api.run("style.add_style", model, name=f"VIKTOR_{_safe_style_name(name)}")
        ifcopenshell.api.run(
            "style.add_surface_style",
            model,
            style=style,
            attributes={"SurfaceColour": {"Red": r, "Green": g, "Blue": b}},
        )

        for mat in mats_by_name.get(name, []):
            try:
                ifcopenshell.api.run("style.assign_material_style", model, material=mat, style=style)
            except Exception:
                # Some IFCs may contain invalid/incomplete material definitions.
                continue


def _create_colored_ifc_file(vkt_ifc_file: vkt.File, include_openings: bool) -> Tuple[vkt.File, Counter, Dict[str, Tuple[int, int, int]]]:
    """Returns: (colored IFC file, material counts, material->rgb)."""

    model = _open_ifc_model_from_vkt_file(vkt_ifc_file)
    counts, colors = _build_counts_and_colors(model, include_openings=include_openings)

    _apply_material_based_coloring(model, colors)

    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp_out:
        model.write(tmp_out.name)
        colored_file = vkt.File.from_path(Path(tmp_out.name))

    return colored_file, counts, colors


def _get_material_summary(vkt_ifc_file: vkt.File, include_openings: bool) -> Tuple[Counter, Dict[str, Tuple[int, int, int]]]:
    model = _open_ifc_model_from_vkt_file(vkt_ifc_file)
    return _build_counts_and_colors(model, include_openings=include_openings)


class Parametrization(vkt.Parametrization):
    page = vkt.Page("Model", views=["ifc_view", "materials_table"])

    page.tab = vkt.Tab("Inputs")
    page.tab.inputs = vkt.Section("IFC upload")
    page.tab.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # IFC Material Explorer

            Upload an IFC file to:

            - View the model in 3D
            - Automatically color elements **per material** (unique color per material)
            - Get a **material take-off**: material name vs. count of elements using it

            Notes:
            - If an element has a layered material set (e.g., a wall build-up), it will be counted once for each material in that set.
            """
        )
    )
    page.tab.inputs.ifc_file = vkt.FileField("IFC file", file_types=[".ifc"])
    page.tab.inputs.include_openings = vkt.BooleanField("Include openings (IfcOpeningElement) in counts", default=False)


class Controller(vkt.Controller):
    label = "IFC Material Explorer"
    parametrization = Parametrization(width=35)

    @vkt.IFCView("3D IFC viewer (colored)", duration_guess=5, x_axis_to_right=True)
    def ifc_view(self, params, **kwargs):
        if params.page.tab.inputs.ifc_file is None:
            raise vkt.UserError("Please upload an IFC file.")

        colored_ifc, _, _ = _create_colored_ifc_file(
            params.page.tab.inputs.ifc_file.file,
            include_openings=bool(params.page.tab.inputs.include_openings),
        )
        return vkt.IFCResult(colored_ifc)

    @vkt.TableView("Materials summary", duration_guess=2)
    def materials_table(self, params, **kwargs):
        if params.page.tab.inputs.ifc_file is None:
            raise vkt.UserError("Please upload an IFC file.")

        counts, colors = _get_material_summary(
            params.page.tab.inputs.ifc_file.file,
            include_openings=bool(params.page.tab.inputs.include_openings),
        )

        rows = []
        for mat_name, cnt in sorted(counts.items(), key=lambda x: (-x[1], x[0].lower())):
            rgb = colors.get(mat_name, DEFAULT_NO_MATERIAL_RGB)
            rows.append([TableCell(" ", background_color=Color(*rgb)), mat_name, int(cnt)])

        return vkt.TableResult(rows, column_headers=["Color", "Material", "# elements"])
